BEGIN;

-- mcp_registry_cache
CREATE TABLE mcp_registry_cache (
	registry_id VARCHAR(255) NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	description TEXT NOT NULL, 
	server_url VARCHAR(1000) NOT NULL, 
	auth_type VARCHAR(50) NOT NULL, 
	categories TEXT[], 
	tools_count INTEGER NOT NULL, 
	popularity_score INTEGER NOT NULL, 
	verified BOOLEAN NOT NULL, 
	id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_mcp_registry_cache_registry_id ON mcp_registry_cache (registry_id);

-- tenants
CREATE TABLE tenants (
	name VARCHAR(255) NOT NULL, 
	slug VARCHAR(255) NOT NULL, 
	plan tenant_plan NOT NULL, 
	stripe_customer_id VARCHAR(255), 
	settings JSONB, 
	slack_webhook_url TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	daily_cost_limit NUMERIC(10, 2), 
	monthly_cost_limit NUMERIC(10, 2), 
	id UUID NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_tenants_slug ON tenants (slug);

-- activity_logs
CREATE TABLE activity_logs (
