CREATE INDEX ix_persona_items_tenant_id ON persona_items (tenant_id);
CREATE INDEX ix_persona_items_persona_scope ON persona_items (persona_scope);
CREATE INDEX ix_persona_items_user_scope ON persona_items (user_id, persona_scope);
CREATE INDEX ix_persona_items_user_id ON persona_items (user_id);

-- pipeline_run_diffs
CREATE TABLE pipeline_run_diffs (
	pipeline_id UUID NOT NULL, 
	execution_id UUID NOT NULL, 
	node_id VARCHAR(255) NOT NULL, 
	node_kind VARCHAR(64) NOT NULL, 
	node_target VARCHAR(255), 
	error_class VARCHAR(128) NOT NULL, 
	error_message TEXT NOT NULL, 
	error_traceback TEXT, 
	expected_shape JSONB, 
	observed_shape JSONB, 
	expected_sample JSONB, 
	observed_sample JSONB, 
	upstream_inputs JSONB, 
	recent_success_count INTEGER NOT NULL, 
	recent_failure_count INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	id UUID NOT NULL, 
	tenant_id UUID NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(pipeline_id) REFERENCES agents (id) ON DELETE CASCADE, 
	FOREIGN KEY(execution_id) REFERENCES executions (id) ON DELETE CASCADE, 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id)
);

CREATE INDEX ix_pipeline_run_diffs_pipeline_id ON pipeline_run_diffs (pipeline_id);
CREATE INDEX ix_pipeline_run_diffs_execution_id ON pipeline_run_diffs (execution_id);
CREATE INDEX ix_pipeline_run_diffs_tenant_id ON pipeline_run_diffs (tenant_id);

-- retrieval_feedback
CREATE TABLE retrieval_feedback (
	kb_id UUID NOT NULL, 
	execution_id UUID, 
	query TEXT NOT NULL, 
	search_mode VARCHAR(50) NOT NULL, 
	result_entity_ids JSONB, 
	result_chunk_ids JSONB, 
	rating INTEGER NOT NULL, 
	comment TEXT, 
	latency_ms INTEGER NOT NULL, 
	result_count INTEGER NOT NULL, 
	id UUID NOT NULL, 
	tenant_id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(kb_id) REFERENCES knowledge_collections (id), 
	FOREIGN KEY(execution_id) REFERENCES executions (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id)
);

CREATE INDEX ix_retrieval_feedback_kb_id ON retrieval_feedback (kb_id);
CREATE INDEX ix_retrieval_feedback_kb_mode ON retrieval_feedback (kb_id, search_mode);
CREATE INDEX ix_retrieval_feedback_tenant_id ON retrieval_feedback (tenant_id);
CREATE INDEX ix_retrieval_feedback_kb_exec ON retrieval_feedback (kb_id, execution_id);

-- retrieval_metrics
CREATE TABLE retrieval_metrics (
	kb_id UUID NOT NULL, 
	agent_id UUID, 
	period_start TIMESTAMP WITH TIME ZONE NOT NULL, 
	period_end TIMESTAMP WITH TIME ZONE NOT NULL, 
	search_mode VARCHAR(50) NOT NULL, 
	query_count INTEGER NOT NULL, 
	avg_rating NUMERIC(5, 4), 
	avg_latency_ms INTEGER NOT NULL, 
	p95_latency_ms INTEGER NOT NULL, 
	positive_feedback INTEGER NOT NULL, 
	negative_feedback INTEGER NOT NULL, 
	graph_hops_used INTEGER NOT NULL, 
	entities_in_results INTEGER NOT NULL, 
	id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(kb_id) REFERENCES knowledge_collections (id), 
	FOREIGN KEY(agent_id) REFERENCES agents (id)
);

CREATE INDEX ix_retrieval_metrics_kb_id ON retrieval_metrics (kb_id);
CREATE INDEX ix_retrieval_metrics_kb_mode_period ON retrieval_metrics (kb_id, search_mode, period_start);

-- user_collection_grants
CREATE TABLE user_collection_grants (
	user_id UUID NOT NULL, 
	collection_id UUID NOT NULL, 
	permission collection_permission NOT NULL, 
	granted_by UUID, 
	granted_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE, 
	id UUID NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_user_collection_grant UNIQUE (user_id, collection_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(collection_id) REFERENCES knowledge_collections (id) ON DELETE CASCADE, 
	FOREIGN KEY(granted_by) REFERENCES users (id)
);

CREATE INDEX ix_user_collection_grants_user ON user_collection_grants (user_id);
CREATE INDEX ix_user_collection_grants_collection ON user_collection_grants (collection_id);

-- cognify_reports
CREATE TABLE cognify_reports (
	job_id UUID NOT NULL, 
	kb_id UUID NOT NULL, 
	entities_by_type JSONB NOT NULL, 
	top_entities JSONB NOT NULL, 
	relationship_types JSONB NOT NULL, 
	new_entities INTEGER NOT NULL, 
	merged_entities INTEGER NOT NULL, 
	new_relationships INTEGER NOT NULL, 
	strengthened_relationships INTEGER NOT NULL, 
	documents_processed INTEGER NOT NULL, 
	chunks_analyzed INTEGER NOT NULL, 
	processing_details JSONB, 
	id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (job_id), 
	FOREIGN KEY(job_id) REFERENCES cognify_jobs (id), 
	FOREIGN KEY(kb_id) REFERENCES knowledge_collections (id)
);

CREATE INDEX ix_cognify_reports_kb_id ON cognify_reports (kb_id);

-- graph_relationships
CREATE TABLE graph_relationships (
	kb_id UUID NOT NULL, 
	source_entity_id UUID NOT NULL, 
	target_entity_id UUID NOT NULL, 
	relationship_type VARCHAR(200) NOT NULL, 
	description TEXT, 
	properties JSONB, 
	source_doc_ids JSONB, 
	neo4j_rel_id VARCHAR(100), 
	weight NUMERIC(5, 4) NOT NULL, 
	access_count INTEGER NOT NULL, 
	confidence NUMERIC(5, 4) NOT NULL, 
	id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(kb_id) REFERENCES knowledge_collections (id), 
	FOREIGN KEY(source_entity_id) REFERENCES graph_entities (id), 
	FOREIGN KEY(target_entity_id) REFERENCES graph_entities (id)
);

CREATE INDEX ix_graph_rels_source_target ON graph_relationships (source_entity_id, target_entity_id);
CREATE INDEX ix_graph_rels_kb_type ON graph_relationships (kb_id, relationship_type);
CREATE INDEX ix_graph_relationships_kb_id ON graph_relationships (kb_id);

-- pipeline_patch_proposals
CREATE TABLE pipeline_patch_proposals (
	pipeline_id UUID NOT NULL, 
	triggering_diff_id UUID, 
	triggering_execution_id UUID, 
	author_agent_id UUID, 
	title VARCHAR(255) NOT NULL, 
	rationale TEXT NOT NULL, 
	confidence NUMERIC(3, 2) NOT NULL, 
	risk_level VARCHAR(16) NOT NULL, 
	dsl_before JSONB NOT NULL, 
	json_patch JSONB NOT NULL, 
	dsl_after JSONB NOT NULL, 
	dsl_before_sha256 VARCHAR(64), 
	applied_snapshot JSONB, 
	status pipeline_patch_status NOT NULL, 
	decided_by UUID, 
	decided_at TIMESTAMP WITH TIME ZONE, 
	rolled_back_at TIMESTAMP WITH TIME ZONE, 
	rolled_back_by UUID, 
	id UUID NOT NULL, 
	tenant_id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(pipeline_id) REFERENCES agents (id) ON DELETE CASCADE, 
	FOREIGN KEY(triggering_diff_id) REFERENCES pipeline_run_diffs (id) ON DELETE SET NULL, 
	FOREIGN KEY(triggering_execution_id) REFERENCES executions (id) ON DELETE SET NULL, 
	FOREIGN KEY(decided_by) REFERENCES users (id), 
	FOREIGN KEY(rolled_back_by) REFERENCES users (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id)
);

CREATE INDEX ix_pipeline_patch_proposals_pipeline_id ON pipeline_patch_proposals (pipeline_id);
CREATE INDEX ix_pipeline_patch_proposals_tenant_id ON pipeline_patch_proposals (tenant_id);

COMMIT;
